func:
// Clear previous partial reads
flow.set("pfs_part_pvmppt14", undefined);
flow.set("pfs_part_pvmppt58", undefined);
flow.set("pfs_part_gridbatt", undefined);
flow.set("pfs_part_loadgen", undefined);

// Preserve RPC context if present
const isRpc = msg.isRpcRequest === true;
if (isRpc) {
    flow.set("pfs_rpc_context", {
        requestId: msg.rpcRequestId,
        responseTopic: msg.rpcResponseTopic
    });
} else {
    flow.set("pfs_rpc_context", undefined);
}

return msg;

// Read registers 672-675: PV1-4 input power
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 672,
    quantity: 4
};
return msg;

// Read registers 727-730: PV5-8 power
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 727,
    quantity: 4
};
return msg;

// Read registers 590, 625, 690
// We'll read 590, then 625, then 690 separately
// For simplicity, read 590-590, then 625-625, then 690-690
// Better approach: read 590, then 625+690 in one read
// But they're far apart, so read separately

// Actually, let's read 625 and 690 (Grid low+high)
// And 590 separately
// Since 625 and 690 are far apart (65 registers), read separately

// Read 590 (Battery), 625 (Grid low), 690 (Grid high)
// Strategy: Read 590 alone, then read 625, then read 690
// But we need all 3 in one partial... let's use multiple reads

// Simpler: Just read what we need
// 590: Battery power
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 590,
    quantity: 1
};
msg.readPart = "battery";
return msg;

// Read registers 653, 659, 667, 671, 718
// 653: Load low
// 659: Load high  
// 667: Gen low
// 671: Gen high
// 718: PV total

// These are scattered, so we'll need multiple reads
// But let's group what we can
// 653-659 is 7 registers apart
// 667-671 is 5 registers apart
// 718 is far

// Read 653, 659 (Load)
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 653,
    quantity: 7  // 653-659
};
msg.readPart = "load_range";
return msg;

const data = msg.payload;
const address = msg.modbusRequest?.address;
const readPart = msg.readPart;

// Helper: s16 conversion
function s16(val) {
    return (val & 0x8000) ? val - 0x10000 : val;
}

// Helper: u32 from two words
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// Helper: s32 from two words
function s32(low, high) {
    const val = u32(low, high);
    return (val & 0x80000000) ? val - 0x100000000 : val;
}

// Determine which part this is
if (address === 672) {
    // PV MPPT 1-4
    const pv1 = data[0] || 0;  // 672
    const pv2 = data[1] || 0;  // 673
    const pv3 = data[2] || 0;  // 674
    const pv4 = data[3] || 0;  // 675

    flow.set("pfs_part_pvmppt14", {
        pv1, pv2, pv3, pv4
    });

} else if (address === 727) {
    // PV MPPT 5-8
    const pv5 = data[0] || 0;  // 727
    const pv6 = data[1] || 0;  // 728
    const pv7 = data[2] || 0;  // 729
    const pv8 = data[3] || 0;  // 730

    flow.set("pfs_part_pvmppt58", {
        pv5, pv6, pv7, pv8
    });

} else if (address === 590 && readPart === "battery") {
    // Battery power
    const batteryPower = s16(data[0] || 0);  // 590: S16, 1W or 10W

    flow.set("pfs_part_battery", batteryPower);

    // Now read Grid low (625)
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 625,
        quantity: 1
    };
    msg.readPart = "grid_low";
    return msg;

} else if (address === 625 && readPart === "grid_low") {
    // Grid low word
    const gridLow = data[0] || 0;
    flow.set("pfs_part_grid_low", gridLow);

    // Now read Grid high (690)
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 690,
        quantity: 1
    };
    msg.readPart = "grid_high";
    return msg;

} else if (address === 690 && readPart === "grid_high") {
    // Grid high word
    const gridHigh = data[0] || 0;
    flow.set("pfs_part_grid_high", gridHigh);

    // Mark grid+batt complete
    flow.set("pfs_part_gridbatt", true);

} else if (address === 653 && readPart === "load_range") {
    // Load range 653-659 (7 registers)
    const loadLow = data[0] || 0;   // 653
    const loadHigh = data[6] || 0;  // 659

    flow.set("pfs_part_load_low", loadLow);
    flow.set("pfs_part_load_high", loadHigh);

    // Now read Gen low+high (667-671 is 5 registers)
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 667,
        quantity: 5
    };
    msg.readPart = "gen_range";
    return msg;

} else if (address === 667 && readPart === "gen_range") {
    // Gen range 667-671
    const genLow = data[0] || 0;   // 667
    const genHigh = data[4] || 0;  // 671

    flow.set("pfs_part_gen_low", genLow);
    flow.set("pfs_part_gen_high", genHigh);

    // Now read PV total (718)
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 718,
        quantity: 1
    };
    msg.readPart = "pv_total";
    return msg;

} else if (address === 718 && readPart === "pv_total") {
    // PV total power
    const pvTotal = data[0] || 0;  // 718
    flow.set("pfs_part_pv_total", pvTotal);

    // Mark load+gen complete
    flow.set("pfs_part_loadgen", true);
}

// Check if all parts are ready
const pvmppt14 = flow.get("pfs_part_pvmppt14");
const pvmppt58 = flow.get("pfs_part_pvmppt58");
const gridbatt = flow.get("pfs_part_gridbatt");
const loadgen = flow.get("pfs_part_loadgen");

if (!pvmppt14 || !pvmppt58 || !gridbatt || !loadgen) {
    return null;  // Wait for all parts
}

// All parts ready - assemble payload
const batteryPower = flow.get("pfs_part_battery");
const gridLow = flow.get("pfs_part_grid_low");
const gridHigh = flow.get("pfs_part_grid_high");
const loadLow = flow.get("pfs_part_load_low");
const loadHigh = flow.get("pfs_part_load_high");
const genLow = flow.get("pfs_part_gen_low");
const genHigh = flow.get("pfs_part_gen_high");
const pvTotal = flow.get("pfs_part_pv_total");

// Combine 32-bit values
const gridPower = s32(gridLow, gridHigh);
const loadPower = s32(loadLow, loadHigh);
const genPower = s32(genLow, genHigh);

// Build telemetry
const telemetry = {
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: "loftty-inverter",

    pv: {
        totalPowerW: pvTotal,
        mppt: [
            { id: 1, powerW: pvmppt14.pv1 },
            { id: 2, powerW: pvmppt14.pv2 },
            { id: 3, powerW: pvmppt14.pv3 },
            { id: 4, powerW: pvmppt14.pv4 },
            { id: 5, powerW: pvmppt58.pv5 === 0 ? null : pvmppt58.pv5 },
            { id: 6, powerW: pvmppt58.pv6 === 0 ? null : pvmppt58.pv6 },
            { id: 7, powerW: pvmppt58.pv7 === 0 ? null : pvmppt58.pv7 },
            { id: 8, powerW: pvmppt58.pv8 === 0 ? null : pvmppt58.pv8 }
        ]
    },

    grid: {
        totalPowerW: gridPower
    },

    load: {
        totalPowerW: loadPower
    },

    battery: {
        powerW: batteryPower
    },

    generator: {
        totalPowerW: genPower
    }
};

// Clear flow context
flow.set("pfs_part_pvmppt14", undefined);
flow.set("pfs_part_pvmppt58", undefined);
flow.set("pfs_part_battery", undefined);
flow.set("pfs_part_grid_low", undefined);
flow.set("pfs_part_grid_high", undefined);
flow.set("pfs_part_load_low", undefined);
flow.set("pfs_part_load_high", undefined);
flow.set("pfs_part_gen_low", undefined);
flow.set("pfs_part_gen_high", undefined);
flow.set("pfs_part_pv_total", undefined);
flow.set("pfs_part_gridbatt", undefined);
flow.set("pfs_part_loadgen", undefined);

// Check if RPC
const rpcContext = flow.get("pfs_rpc_context");
if (rpcContext) {
    msg.topic = rpcContext.responseTopic;
    msg.payload = telemetry;
    flow.set("pfs_rpc_context", undefined);
    return [msg, null];  // Send to RPC output only
} else {
    msg.payload = telemetry;
    return [null, msg];  // Send to telemetry output only
}
